// Generated by Claude Code
package grading.feedback;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * One of the student's source files as they submitted it, with the lines they kept unchanged from
 * the template. Finds methods and statements by reading the text, so it also works on code that
 * does not compile.
 *
 * @param name       the file name, such as Q1a.java
 * @param lines      the file's lines, as submitted
 * @param keptLines  1-based numbers of the lines kept unchanged from the template
 */
record SourceFile(String name, List<String> lines, Set<Integer> keptLines) {

    private static final Pattern LOOP = Pattern.compile("\\b(for|while|do)\\b\\s*[({]");
    private static final Pattern RETURN = Pattern.compile("\\breturn\\b");
    private static final Pattern CONTROL_WORD = Pattern.compile("^(if|for|while|switch|catch|return|new|else)\\b");

    SourceFile {
        lines = List.copyOf(lines);
        keptLines = Set.copyOf(keptLines);
    }

    /** The text of a 1-based line, without its indentation; empty when out of range. */
    String code(int line) {
        return line < 1 || line > lines.size() ? "" : lines.get(line - 1).strip();
    }

    /** Where the given line of this file is, for a piece of feedback. */
    SourceLocation at(int line) {
        return new SourceLocation(name, line, code(line));
    }

    /** The declaration of the method with this name, such as getAverageAge, and its body. */
    Optional<MethodSpan> method(String methodName) {
        Pattern declaration = Pattern.compile("[\\w>\\]]\\s+" + Pattern.quote(methodName) + "\\s*\\(");
        for (int index = 0; index < lines.size(); index++) {
            String text = withoutComment(lines.get(index)).strip();
            if (declaration.matcher(text).find() && !text.endsWith(";") && !CONTROL_WORD.matcher(text).find()
                    && !text.contains("=")) {
                int start = index + 1;
                return Optional.of(new MethodSpan(methodName, start, blockEnd(start)));
            }
        }
        return Optional.empty();
    }

    /** Lines inside the method that start a for, while or do loop. */
    List<Integer> loops(MethodSpan method) {
        return linesMatching(method, LOOP);
    }

    /** Lines inside the method that return a value. */
    List<Integer> returns(MethodSpan method) {
        return linesMatching(method, RETURN);
    }

    /**
     * True when every statement in the method's body is still the template's: the student has not
     * written any code of their own in it.
     */
    boolean isStarterCode(MethodSpan method) {
        if (keptLines.isEmpty()) {
            return false;
        }
        for (int line = method.start() + 1; line < method.end(); line++) {
            String code = withoutComment(lines.get(line - 1)).strip();
            boolean ownCode = !code.isEmpty() && !code.equals("{") && !code.equals("}");
            if (ownCode && !keptLines.contains(line)) {
                return false;
            }
        }
        return true;
    }

    /**
     * The line of this file holding the same code as the given line of the copy that was compiled;
     * that copy may have extra header lines, so the numbers can differ.
     */
    Optional<Integer> lineMatching(String compiledCode, int compiledLine) {
        String wanted = compiledCode.strip();
        if (wanted.isEmpty()) {
            return Optional.empty();
        }
        Integer best = null;
        for (int line = 1; line <= lines.size(); line++) {
            if (code(line).equals(wanted)
                    && (best == null || Math.abs(line - compiledLine) < Math.abs(best - compiledLine))) {
                best = line;
            }
        }
        return Optional.ofNullable(best);
    }

    /** The first line inside the method whose code matches the pattern, or empty. */
    Optional<Integer> firstLine(MethodSpan method, Pattern pattern) {
        return linesMatching(method, pattern).stream().findFirst();
    }

    private List<Integer> linesMatching(MethodSpan method, Pattern pattern) {
        List<Integer> found = new ArrayList<>();
        for (int line = method.start(); line <= method.end(); line++) {
            if (pattern.matcher(withoutStrings(withoutComment(lines.get(line - 1)))).find()) {
                found.add(line);
            }
        }
        return found;
    }

    /** The line holding the brace that closes the block opened on or after the start line. */
    int blockEnd(int start) {
        int depth = 0;
        boolean opened = false;
        for (int line = start; line <= lines.size(); line++) {
            for (char c : withoutStrings(withoutComment(lines.get(line - 1))).toCharArray()) {
                if (c == '{') {
                    depth++;
                    opened = true;
                } else if (c == '}') {
                    depth--;
                    if (opened && depth == 0) {
                        return line;
                    }
                }
            }
        }
        return lines.size();
    }

    // Drops a // comment so braces and keywords in it are not counted. Block comments are rare inside methods.
    static String withoutComment(String line) {
        int comment = withoutStrings(line).indexOf("//");
        return comment < 0 ? line : line.substring(0, comment);
    }

    // Blanks out string and character literals, keeping the length, so their braces are not counted.
    static String withoutStrings(String line) {
        StringBuilder out = new StringBuilder(line.length());
        char quote = 0;
        for (int index = 0; index < line.length(); index++) {
            char c = line.charAt(index);
            if (quote != 0) {
                if (c == quote) {
                    quote = 0;
                    out.append(c);
                } else {
                    out.append(' ');
                    if (c == '\\' && index + 1 < line.length()) {
                        out.append(' ');
                        index++;
                    }
                }
            } else {
                if (c == '"' || c == '\'') {
                    quote = c;
                }
                out.append(c);
            }
        }
        return out.toString();
    }
}
